const vec3 DARKGREY = vec3(0.1);
const vec3 LIGHTGREY = vec3(0.2);
const vec3 WHITE = vec3(1);
const vec3 AMBER = vec3(1, 0.49, 0);
const vec3 TRON_BLUE = vec3(0.1, 0.5, 0.8);

const vec3 HEX_BORDER = LIGHTGREY;
const vec3 HEX_BODY = DARKGREY;
const vec3 HAZE = LIGHTGREY;
const float HEX_SIZE = 18.0;

ivec3 cube_round(vec3 h) {
    vec3 r = floor(h + 0.5);
    vec3 diff = abs(r - h);
    if (diff.x > diff.y && diff.x > diff.z) {
        r.x = -r.y - r.z;
    } else if (diff.y > diff.z) {
        r.y = -r.x - r.z;
    } else {
        r.z = -r.x - r.y;
    }
    return ivec3(int(r.x), int(r.y), int(r.z));
}

float cube_distance(ivec3 a, ivec3 b) {
    vec3 ab = abs(vec3(a) - vec3(b));

    return max(max(ab.x, ab.y), ab.z);
}

ivec2 cube_to_hex(ivec3 c) {
    return c.xy;
}

ivec3 hex_to_cube(ivec2 h) {
    return ivec3(h.x, h.y, -h.x - h.y);
}

vec3 hex_to_cube(vec2 h) {
    return vec3(h.x, h.y, -h.x - h.y);
}

ivec2 hex_round(vec2 h) {
    return cube_to_hex(cube_round(hex_to_cube(h)));
}

ivec2 pixel_to_hex(in vec2 pixel) {
    const vec2 PIXEL_TO_HEX_CONST = vec2(sqrt(3.0), 2.0) / 3.0;
    vec2 result = PIXEL_TO_HEX_CONST * pixel;
    result.x -= pixel.y / 3.0;

    return hex_round(result);
}

vec2 hex_to_pixel(in ivec2 hex2)  {
    vec2 hex = vec2(hex2);
    return vec2(sqrt(3.0) * (hex.x + hex.y/2.0), 1.5 * hex.y);
}

vec2 hex_center(in vec2 pixel) {
    return hex_to_pixel(pixel_to_hex(pixel));
}

float point_line_distance(vec2 slope, vec2 p)
{
  vec2 normal = vec2(-slope.y, slope.x);
  return abs(dot(normalize(normal), p));
}


void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec3 col = DARKGREY;

    vec2 xy = 1.0 - 2.0 * fragCoord.xy/iResolution.xy;
    xy *= HEX_SIZE;
    xy.y /= iResolution.x / iResolution.y;
    vec2 mousexy = 1.0 - 2.0 * iMouse.xy/iResolution.xy;
    mousexy.y /=  iResolution.x / iResolution.y;
    mousexy *= HEX_SIZE;


    float lineDist = point_line_distance(mousexy, xy);
    if (lineDist < 0.03) {
        fragColor = vec4(1.0, 0.0, 0.0, 1.0);
        return;
    }

    col = mix(col, vec3(1.0, 0.0, 0.0), smoothstep(0.05, 0.03, lineDist));

    ivec2 hex = pixel_to_hex(xy);
    vec2 hexCenter = hex_to_pixel(hex);


    ivec2 origin = ivec2(0);
    if (hex == origin) {
        fragColor = vec4(0.0, 1.0, 1.0, 1.0);
        return;
    }

    ivec2 mousehex = pixel_to_hex(mousexy);
    ivec3 cur = hex_to_cube(hex);
    ivec3 a = hex_to_cube(origin);
    ivec3 b = hex_to_cube(mousehex);

    if (cur == b) {
        fragColor = vec4(0.0, 0.0, 1.0, 1.0);
        return;
    }


    float cubedist = floor(cube_distance(a, b));
    for (float i = 0.0; i < 10000.0; i += 0.01) {
        if (i > cubedist) {
            break;
        }
        float mixAmount = i / cubedist;
        ivec3 testCube = cube_round(mix(vec3(a), vec3(b), mixAmount));
        ivec2 testHex = cube_to_hex(testCube);
        if (hex == testHex) {
            fragColor = vec4(1.0, 1.0, 1.0, 1.0);
            return;
        }
    }

    vec2 hexPos = hex_to_pixel(hex.xy);
    float dist = length(xy - hexPos);
    if (dist < 0.3) {
        col = vec3(1.0, 0.0, 1.0);
    }
    // gamma
	//col = pow(col,vec3(0.4545));

    // vignetting	
	//col *= 0.5 + 0.5*pow( (xy.x+1.0)*(xy.y+1.0)*(xy.x-1.0)*(xy.y-1.0), 0.1 );

    #ifdef STEREO	
    //col *= vec3( isCyan, 1.0-isCyan, 1.0-isCyan );	
	#endif

	fragColor=vec4(col,1.0);
}
